import Foundation
import CryptoKit

// MARK: - Secure Message Transport Layer
// Implements authenticated encryption for inter-service communication
// Uses AES-GCM with replay protection via nonce tracking

enum SecureChannelError: Error {
    case randomGenerationFailed
}

struct NonceState {
    var counter: UInt64
    var instanceId: Data
    var lastNonce: Data?

    init(instanceId: Data) {
        self.counter = 0
        self.instanceId = instanceId
        self.lastNonce = nil
    }
}

class SecureChannel {
    private let symmetricKey: SymmetricKey
    private var nonceState: NonceState
    private let channelId: String
    private var messageLog: [(timestamp: Date, noncePrefix: Data)] = []
    private let lock = NSLock()

    init(sharedSecret: Data, channelId: String) throws {
        // Derive channel-specific key using HKDF
        let salt = "channel-key-v2-\(channelId)".data(using: .utf8)!
        let derived = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: sharedSecret),
            salt: salt,
            info: "aes-gcm-256".data(using: .utf8)!,
            outputByteCount: 32
        )
        self.symmetricKey = derived
        self.channelId = channelId

        // Generate instance-unique identifier for nonce construction
        var instanceBytes = [UInt8](repeating: 0, count: 4)
        let status = SecRandomCopyBytes(kSecRandomDefault, 4, &instanceBytes)
        guard status == errSecSuccess else {
            throw SecureChannelError.randomGenerationFailed
        }
        self.nonceState = NonceState(instanceId: Data(instanceBytes))
    }

    // MARK: - Nonce Generation
    // Constructs a 12-byte nonce: [4 bytes instance] [8 bytes counter]
    // The instance bytes ensure uniqueness across concurrent channels
    private func generateFreshNonce() -> AES.GCM.Nonce {
        lock.lock()
        defer { lock.unlock() }

        nonceState.counter += 1

        var nonceBytes = [UInt8](repeating: 0, count: 12)
        // First 4 bytes: instance identifier
        nonceState.instanceId.withUnsafeBytes { ptr in
            for i in 0..<4 {
                nonceBytes[i] = ptr[i]
            }
        }
        // Last 8 bytes: monotonic counter
        var counterValue = nonceState.counter
        withUnsafeBytes(of: &counterValue) { ptr in
            for i in 0..<8 {
                nonceBytes[4 + i] = ptr[i]
            }
        }

        let nonceData = Data(nonceBytes)
        nonceState.lastNonce = nonceData

        return try! AES.GCM.Nonce(data: nonceData)
    }

    // MARK: - Batch Encryption Support
    // For high-throughput scenarios, tracks batch metadata
    // Each message still gets a unique nonce for GCM safety
    struct BatchContext {
        let batchId: UUID
        let startTime: Date
        var messageCount: Int = 0
        var batchNonceBase: AES.GCM.Nonce?
    }

    private var currentBatch: BatchContext?

    func beginBatch() -> UUID {
        let batchId = UUID()
        currentBatch = BatchContext(batchId: batchId, startTime: Date())
        return batchId
    }

    func endBatch() {
        currentBatch = nil
    }

    // Core encryption function
    // Always generates a fresh nonce per message regardless of batch mode
    // Batch context is used only for metadata tracking
    func encrypt(plaintext: Data, associatedData: Data? = nil) throws -> AES.GCM.SealedBox {
        let nonce: AES.GCM.Nonce

        if var batch = currentBatch {
            if batch.batchNonceBase == nil {
                // First message in batch - generate fresh nonce as base
                batch.batchNonceBase = generateFreshNonce()
            }
            // Generate a fresh nonce for EACH message in the batch
            // The batch base is stored only for ordering/replay detection
            nonce = generateFreshNonce()
            batch.messageCount += 1
            currentBatch = batch
        } else {
            nonce = generateFreshNonce()
        }

        let sealedBox = try AES.GCM.seal(
            plaintext,
            using: symmetricKey,
            nonce: nonce,
            authenticating: associatedData ?? Data()
        )

        return sealedBox
    }

    // Convenience method for string messages
    func encryptMessage(_ message: String, metadata: [String: String] = [:]) throws -> Data {
        let payload = try JSONSerialization.data(
            withJSONObject: ["msg": message, "meta": metadata, "ts": ISO8601DateFormatter().string(from: Date())],
            options: []
        )

        let aad = channelId.data(using: .utf8)!
        let sealed = try encrypt(plaintext: payload, associatedData: aad)
        return sealed.combined!
    }
}

// MARK: - Service Mesh Integration
// Manages secure channels between microservices
class ServiceMesh {
    private var channels: [String: SecureChannel] = [:]
    private let meshSecret: Data

    init(meshSecret: Data) {
        self.meshSecret = meshSecret
    }

    func getChannel(to service: String) throws -> SecureChannel {
        if let existing = channels[service] {
            return existing
        }
        let channel = try SecureChannel(sharedSecret: meshSecret, channelId: service)
        channels[service] = channel
        return channel
    }

    // High-throughput batch send - sends multiple messages efficiently
    func batchSend(to service: String, messages: [String]) throws -> [Data] {
        let channel = try getChannel(to: service)
        let batchId = channel.beginBatch()
        defer { channel.endBatch() }

        var encrypted: [Data] = []
        for (index, msg) in messages.enumerated() {
            let ciphertext = try channel.encryptMessage(
                msg,
                metadata: ["batch": batchId.uuidString, "seq": "\(index)"]
            )
            encrypted.append(ciphertext)
        }
        return encrypted
    }
}
